class Solution {
  twoSum(nums, target) {
    for (let i = 0; i < nums.length; i++) {
      let complement = target - nums[i];
      let j = nums.indexOf(complement);
      if (j !== -1 && j !== i) { // Fixed self check but fails [3, 3] if duplicate isn't found
        return [i, j];
      }
    }
    return [];
  }
}
